using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using System.Net;

namespace ContosoUniversity.Tests.Controllers;

public class StudentsControllerTests
{
    private SchoolContext CreateContextWithStudents()
    {
        var context = TestDbContext.Create();
        context.Students.AddRange(
            new Student { ID = 1, LastName = "Smith", FirstMidName = "John", EnrollmentDate = new DateTime(2023, 9, 1) },
            new Student { ID = 2, LastName = "Adams", FirstMidName = "Jane", EnrollmentDate = new DateTime(2022, 1, 15) },
            new Student { ID = 3, LastName = "Baker", FirstMidName = "Bob", EnrollmentDate = new DateTime(2023, 1, 10) }
        );
        context.SaveChanges();
        return context;
    }

    [Fact]
    public void Index_NoParameters_ReturnsViewWithStudentsOrderedByLastName()
    {
        using var context = CreateContextWithStudents();
        var controller = new StudentsController(context);

        var result = controller.Index(null, null, null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(3, model.Count);
        Assert.Equal("Adams", model[0].LastName);
        Assert.Equal("Baker", model[1].LastName);
        Assert.Equal("Smith", model[2].LastName);
    }

    [Fact]
    public void Index_NameDescSort_ReturnsStudentsOrderedByLastNameDescending()
    {
        using var context = CreateContextWithStudents();
        var controller = new StudentsController(context);

        var result = controller.Index("name_desc", null, null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal("Smith", model[0].LastName);
        Assert.Equal("Baker", model[1].LastName);
        Assert.Equal("Adams", model[2].LastName);
    }

    [Fact]
    public void Index_DateSort_ReturnsStudentsOrderedByEnrollmentDate()
    {
        using var context = CreateContextWithStudents();
        var controller = new StudentsController(context);

        var result = controller.Index("Date", null, null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal("Adams", model[0].LastName); // 2022-01-15
        Assert.Equal("Baker", model[1].LastName); // 2023-01-10
        Assert.Equal("Smith", model[2].LastName); // 2023-09-01
    }

    [Fact]
    public void Index_DateDescSort_ReturnsStudentsOrderedByEnrollmentDateDescending()
    {
        using var context = CreateContextWithStudents();
        var controller = new StudentsController(context);

        var result = controller.Index("date_desc", null, null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal("Smith", model[0].LastName); // 2023-09-01
    }

    [Fact]
    public void Index_SearchString_FiltersStudentsByName()
    {
        using var context = CreateContextWithStudents();
        var controller = new StudentsController(context);

        var result = controller.Index(null, null, "Smith", null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Single(model);
        Assert.Equal("Smith", model[0].LastName);
    }

    [Fact]
    public void Index_SearchByFirstName_FiltersStudentsByFirstName()
    {
        using var context = CreateContextWithStudents();
        var controller = new StudentsController(context);

        var result = controller.Index(null, null, "Jane", null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Single(model);
        Assert.Equal("Adams", model[0].LastName);
    }

    [Fact]
    public void Index_NewSearchResetsPageToOne()
    {
        using var context = CreateContextWithStudents();
        var controller = new StudentsController(context);

        var result = controller.Index(null, null, "Smith", 5) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(1, model.PageIndex);
    }

    [Fact]
    public void Index_NullSearchUsesCurrentFilter()
    {
        using var context = CreateContextWithStudents();
        var controller = new StudentsController(context);

        var result = controller.Index(null, "Adams", null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Single(model);
        Assert.Equal("Adams", model[0].LastName);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithStudent()
    {
        using var context = CreateContextWithStudents();
        var controller = new StudentsController(context);

        var result = controller.Details(1) as ViewResult;

        Assert.NotNull(result);
        var student = Assert.IsType<Student>(result.Model);
        Assert.Equal("Smith", student.LastName);
        Assert.Equal("John", student.FirstMidName);
    }

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        using var context = CreateContextWithStudents();
        var controller = new StudentsController(context);

        var result = controller.Details(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, result.StatusCode);
    }

    [Fact]
    public void Create_Get_ReturnsViewWithStudentHavingTodayDate()
    {
        using var context = TestDbContext.Create();
        var controller = new StudentsController(context);

        var result = controller.Create() as ViewResult;

        Assert.NotNull(result);
        var student = Assert.IsType<Student>(result.Model);
        Assert.Equal(DateTime.Today, student.EnrollmentDate);
    }

    [Fact]
    public void Create_Post_ValidStudent_AddsAndRedirects()
    {
        using var context = TestDbContext.Create();
        var controller = new StudentsController(context);
        var student = new Student
        {
            LastName = "NewStudent",
            FirstMidName = "Test",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        var result = controller.Create(student) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Single(context.Students);
        Assert.Equal("NewStudent", context.Students.First().LastName);
    }

    [Fact]
    public void Create_Post_MinValueDate_AddsModelError()
    {
        using var context = TestDbContext.Create();
        var controller = new StudentsController(context);
        var student = new Student
        {
            LastName = "Test",
            FirstMidName = "User",
            EnrollmentDate = DateTime.MinValue
        };

        var result = controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.False(controller.ModelState.IsValid);
        Assert.True(controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void Create_Post_DateBefore1753_AddsModelError()
    {
        using var context = TestDbContext.Create();
        var controller = new StudentsController(context);
        var student = new Student
        {
            LastName = "Test",
            FirstMidName = "User",
            EnrollmentDate = new DateTime(1752, 12, 31)
        };

        var result = controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.True(controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithStudent()
    {
        using var context = CreateContextWithStudents();
        var controller = new StudentsController(context);

        var result = controller.Edit(1) as ViewResult;

        Assert.NotNull(result);
        var student = Assert.IsType<Student>(result.Model);
        Assert.Equal("Smith", student.LastName);
    }

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        using var context = CreateContextWithStudents();
        var controller = new StudentsController(context);

        var result = controller.Edit(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, result.StatusCode);
    }

    [Fact]
    public void Edit_Get_InvalidId_ReturnsNotFound()
    {
        using var context = CreateContextWithStudents();
        var controller = new StudentsController(context);

        var result = controller.Edit(999) as NotFoundResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void Edit_Post_ValidStudent_UpdatesAndRedirects()
    {
        using var context = CreateContextWithStudents();
        var controller = new StudentsController(context);
        var student = new Student
        {
            ID = 1,
            LastName = "UpdatedName",
            FirstMidName = "John",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        // Detach the tracked entity first
        var tracked = context.Students.Local.FirstOrDefault(s => s.ID == 1);
        if (tracked != null)
            context.Entry(tracked).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

        var result = controller.Edit(student) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
    }

    [Fact]
    public void Edit_Post_MinValueDate_AddsModelError()
    {
        using var context = CreateContextWithStudents();
        var controller = new StudentsController(context);
        var student = new Student
        {
            ID = 1,
            LastName = "Smith",
            FirstMidName = "John",
            EnrollmentDate = DateTime.MinValue
        };

        var result = controller.Edit(student) as ViewResult;

        Assert.NotNull(result);
        Assert.True(controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithStudent()
    {
        using var context = CreateContextWithStudents();
        var controller = new StudentsController(context);

        var result = controller.Delete(1) as ViewResult;

        Assert.NotNull(result);
        var student = Assert.IsType<Student>(result.Model);
        Assert.Equal("Smith", student.LastName);
    }

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        using var context = CreateContextWithStudents();
        var controller = new StudentsController(context);

        var result = controller.Delete(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, result.StatusCode);
    }

    [Fact]
    public void Delete_Get_InvalidId_ReturnsNotFound()
    {
        using var context = CreateContextWithStudents();
        var controller = new StudentsController(context);

        var result = controller.Delete(999) as NotFoundResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesStudentAndRedirects()
    {
        using var context = CreateContextWithStudents();
        var controller = new StudentsController(context);

        var result = controller.DeleteConfirmed(1) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Equal(2, context.Students.Count());
        Assert.Null(context.Students.Find(1));
    }
}

