using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Moq;
using System.Net;

namespace ContosoUniversity.Tests.Controllers;

public class CoursesControllerTests
{
    private readonly Mock<IWebHostEnvironment> _envMock = new();
    private readonly Mock<ILogger<CoursesController>> _loggerMock = new();

    public CoursesControllerTests()
    {
        _envMock.Setup(e => e.WebRootPath).Returns("/tmp/wwwroot");
        _envMock.Setup(e => e.ContentRootPath).Returns("/tmp");
    }

    private SchoolContext CreateContextWithCourses()
    {
        var context = TestDbContext.Create();
        var dept = new Department { DepartmentID = 1, Name = "Engineering", Budget = 100000m, StartDate = DateTime.Now };
        context.Departments.Add(dept);
        context.Courses.AddRange(
            new Course { CourseID = 1001, Title = "Chemistry", Credits = 3, DepartmentID = 1 },
            new Course { CourseID = 1002, Title = "Physics", Credits = 4, DepartmentID = 1 },
            new Course { CourseID = 1003, Title = "Calculus", Credits = 4, DepartmentID = 1 }
        );
        context.SaveChanges();
        return context;
    }

    [Fact]
    public void Index_ReturnsViewWithAllCourses()
    {
        using var context = CreateContextWithCourses();
        var controller = new CoursesController(context, _envMock.Object, _loggerMock.Object);

        var result = controller.Index() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsAssignableFrom<List<Course>>(result.Model);
        Assert.Equal(3, model.Count);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithCourse()
    {
        using var context = CreateContextWithCourses();
        var controller = new CoursesController(context, _envMock.Object, _loggerMock.Object);

        var result = controller.Details(1001) as ViewResult;

        Assert.NotNull(result);
        var course = Assert.IsType<Course>(result.Model);
        Assert.Equal("Chemistry", course.Title);
        Assert.Equal(3, course.Credits);
    }

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        using var context = CreateContextWithCourses();
        var controller = new CoursesController(context, _envMock.Object, _loggerMock.Object);

        var result = controller.Details(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, result.StatusCode);
    }

    [Fact]
    public void Create_Get_ReturnsViewWithDepartmentSelectList()
    {
        using var context = CreateContextWithCourses();
        var controller = new CoursesController(context, _envMock.Object, _loggerMock.Object);

        var result = controller.Create() as ViewResult;

        Assert.NotNull(result);
        Assert.NotNull(controller.ViewBag.DepartmentID);
    }

    [Fact]
    public void Create_Post_ValidCourse_NoImage_AddsAndRedirects()
    {
        using var context = CreateContextWithCourses();
        var controller = new CoursesController(context, _envMock.Object, _loggerMock.Object);
        var course = new Course
        {
            CourseID = 2001,
            Title = "New Course",
            Credits = 3,
            DepartmentID = 1
        };

        var result = controller.Create(course, null!) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.NotNull(context.Courses.Find(2001));
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsViewWithCourse()
