using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using System.Net;

namespace ContosoUniversity.Tests.Controllers;

public class DepartmentsControllerTests
{
    private SchoolContext CreateContextWithDepartments()
    {
        var context = TestDbContext.Create();
        var instructor = new Instructor { ID = 1, LastName = "Kapoor", FirstMidName = "Raj", HireDate = new DateTime(2010, 1, 1) };
        context.Instructors.Add(instructor);
        context.Departments.AddRange(
            new Department { DepartmentID = 1, Name = "Engineering", Budget = 200000m, StartDate = new DateTime(2000, 9, 1), InstructorID = 1 },
            new Department { DepartmentID = 2, Name = "Science", Budget = 150000m, StartDate = new DateTime(2005, 1, 1), InstructorID = null },
            new Department { DepartmentID = 3, Name = "Arts", Budget = 100000m, StartDate = new DateTime(2010, 6, 1), InstructorID = null }
        );
        context.SaveChanges();
        return context;
    }

    [Fact]
    public void Index_ReturnsViewWithAllDepartments()
    {
        using var context = CreateContextWithDepartments();
        var controller = new DepartmentsController(context);

        var result = controller.Index() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsAssignableFrom<List<Department>>(result.Model);
        Assert.Equal(3, model.Count);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithDepartment()
    {
        using var context = CreateContextWithDepartments();
        var controller = new DepartmentsController(context);

        var result = controller.Details(1) as ViewResult;

        Assert.NotNull(result);
        var dept = Assert.IsType<Department>(result.Model);
        Assert.Equal("Engineering", dept.Name);
        Assert.Equal(200000m, dept.Budget);
    }

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        using var context = CreateContextWithDepartments();
        var controller = new DepartmentsController(context);

        var result = controller.Details(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, result.StatusCode);
    }

    [Fact]
    public void Details_InvalidId_ReturnsNotFound()
    {
        using var context = CreateContextWithDepartments();
        var controller = new DepartmentsController(context);

        var result = controller.Details(999) as NotFoundResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void Create_Get_ReturnsViewWithInstructorSelectList()
    {
        using var context = CreateContextWithDepartments();
        var controller = new DepartmentsController(context);

        var result = controller.Create() as ViewResult;

        Assert.NotNull(result);
        Assert.NotNull(controller.ViewBag.InstructorID);
    }

    [Fact]
    public void Create_Post_ValidDepartment_AddsAndRedirects()
    {
        using var context = CreateContextWithDepartments();
        var controller = new DepartmentsController(context);
        var dept = new Department
        {
            Name = "Mathematics",
            Budget = 120000m,
            StartDate = new DateTime(2020, 1, 1),
            InstructorID = 1
        };

        var result = controller.Create(dept) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Equal(4, context.Departments.Count());
    }

    [Fact]
    public void Create_Post_InvalidModel_ReturnsViewWithInstructorList()
    {
        using var context = CreateContextWithDepartments();
        var controller = new DepartmentsController(context);
        controller.ModelState.AddModelError("Name", "Required");
        var dept = new Department { Name = "", Budget = 0, StartDate = DateTime.Now };

        var result = controller.Create(dept) as ViewResult;

        Assert.NotNull(result);
        Assert.NotNull(controller.ViewBag.InstructorID);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithDepartment()
    {
        using var context = CreateContextWithDepartments();
        var controller = new DepartmentsController(context);

        var result = controller.Edit(1) as ViewResult;

        Assert.NotNull(result);
        var dept = Assert.IsType<Department>(result.Model);
        Assert.Equal("Engineering", dept.Name);
        Assert.NotNull(controller.ViewBag.InstructorID);
    }

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        using var context = CreateContextWithDepartments();
        var controller = new DepartmentsController(context);

        var result = controller.Edit(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, result.StatusCode);
    }

    [Fact]
    public void Edit_Get_InvalidId_ReturnsNotFound()
    {
        using var context = CreateContextWithDepartments();
        var controller = new DepartmentsController(context);

        var result = controller.Edit(999) as NotFoundResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void Edit_Post_ValidDepartment_UpdatesAndRedirects()
    {
        using var context = CreateContextWithDepartments();
        var controller = new DepartmentsController(context);
        var dept = new Department
        {
            DepartmentID = 1,
            Name = "Updated Engineering",
            Budget = 250000m,
            StartDate = new DateTime(2000, 9, 1),
            InstructorID = 1
        };

        // Detach tracked entity
        var tracked = context.Departments.Local.FirstOrDefault(d => d.DepartmentID == 1);
        if (tracked != null)
            context.Entry(tracked).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

        var result = controller.Edit(dept) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
    }

    [Fact]
    public void Edit_Post_InvalidModel_ReturnsViewWithInstructorList()
    {
        using var context = CreateContextWithDepartments();
        var controller = new DepartmentsController(context);
        controller.ModelState.AddModelError("Name", "Required");
        var dept = new Department { DepartmentID = 1, Name = "", Budget = 0, StartDate = DateTime.Now };

        var result = controller.Edit(dept) as ViewResult;

        Assert.NotNull(result);
        Assert.NotNull(controller.ViewBag.InstructorID);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithDepartment()
    {
        using var context = CreateContextWithDepartments();
        var controller = new DepartmentsController(context);

        var result = controller.Delete(1) as ViewResult;

        Assert.NotNull(result);
        var dept = Assert.IsType<Department>(result.Model);
        Assert.Equal("Engineering", dept.Name);
    }

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        using var context = CreateContextWithDepartments();
        var controller = new DepartmentsController(context);

        var result = controller.Delete(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, result.StatusCode);
    }

    [Fact]
    public void Delete_Get_InvalidId_ReturnsNotFound()
    {
        using var context = CreateContextWithDepartments();
        var controller = new DepartmentsController(context);

        var result = controller.Delete(999) as NotFoundResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesDepartmentAndRedirects()
    {
        using var context = CreateContextWithDepartments();
        var controller = new DepartmentsController(context);

        var result = controller.DeleteConfirmed(2) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Null(context.Departments.Find(2));
        Assert.Equal(2, context.Departments.Count());
    }
}

