using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests.Controllers;

public class HomeControllerTests
{
    [Fact]
    public void Index_ReturnsView()
    {
        using var context = TestDbContext.Create();
        var controller = new HomeController(context);

        var result = controller.Index() as ViewResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void About_ReturnsViewWithEnrollmentDateGroups()
    {
        using var context = TestDbContext.Create();
        context.Students.AddRange(
            new Student { ID = 1, LastName = "A", FirstMidName = "B", EnrollmentDate = new DateTime(2023, 9, 1) },
            new Student { ID = 2, LastName = "C", FirstMidName = "D", EnrollmentDate = new DateTime(2023, 9, 1) },
            new Student { ID = 3, LastName = "E", FirstMidName = "F", EnrollmentDate = new DateTime(2022, 1, 15) }
        );
        context.SaveChanges();

        var controller = new HomeController(context);

        var result = controller.About() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(result.Model);
        Assert.Equal(2, model.Count);
        var sept2023 = model.FirstOrDefault(g => g.EnrollmentDate == new DateTime(2023, 9, 1));
        Assert.NotNull(sept2023);
        Assert.Equal(2, sept2023.StudentCount);
    }

    [Fact]
    public void Contact_ReturnsViewWithMessage()
    {
        using var context = TestDbContext.Create();
        var controller = new HomeController(context);

        var result = controller.Contact() as ViewResult;

        Assert.NotNull(result);
        Assert.Equal("Your contact page.", controller.ViewBag.Message);
    }

    [Fact]
    public void Error_ReturnsView()
    {
        using var context = TestDbContext.Create();
        var controller = new HomeController(context);

        var result = controller.Error() as ViewResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void Unauthorized_ReturnsViewWithMessage()
    {
        using var context = TestDbContext.Create();
        var controller = new HomeController(context);

        var result = controller.Unauthorized() as ViewResult;

        Assert.NotNull(result);
        Assert.Equal("You don't have permission to access this resource.", controller.ViewBag.Message);
    }
}

