using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests.Controllers;

public class NotificationsControllerTests
{
    [Fact]
    public void GetNotifications_NoNotifications_ReturnsEmptyList()
    {
        using var context = TestDbContext.Create();
        var controller = new NotificationsController(context);

        var result = controller.GetNotifications() as JsonResult;

        Assert.NotNull(result);
        // The result value has success=true and count=0
        var value = result.Value;
        Assert.NotNull(value);
    }

    [Fact]
    public void GetNotifications_WithQueuedNotifications_ReturnsNotifications()
    {
        using var context = TestDbContext.Create();
        var controller = new NotificationsController(context);

        // Queue a notification through the service
        var service = new NotificationService();
        service.SendNotification("Student", "1", "Test Student", EntityOperation.CREATE, "TestUser");

        var result = controller.GetNotifications() as JsonResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void MarkAsRead_ReturnsSuccessJson()
    {
        using var context = TestDbContext.Create();
        var controller = new NotificationsController(context);

        var result = controller.MarkAsRead(1) as JsonResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void Index_ReturnsView()
    {
        using var context = TestDbContext.Create();
        var controller = new NotificationsController(context);

        var result = controller.Index() as ViewResult;

        Assert.NotNull(result);
    }
}

