using ContosoUniversity.Models;
using ContosoUniversity.Services;

namespace ContosoUniversity.Tests.Services;

public class NotificationServiceTests
{
    [Fact]
    public void SendNotification_WithDisplayName_EnqueuesNotificationWithCorrectMessage()
    {
        var service = new NotificationService();

        service.SendNotification("Student", "42", "John Smith", EntityOperation.CREATE, "Admin");

        var notification = service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("42", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Contains("John Smith", notification.Message);
        Assert.Contains("created", notification.Message);
        Assert.Equal("Admin", notification.CreatedBy);
        Assert.False(notification.IsRead);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_UsesEntityIdInMessage()
    {
        var service = new NotificationService();

        service.SendNotification("Course", "101", EntityOperation.UPDATE, "Teacher");

        var notification = service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains("ID: 101", notification.Message);
        Assert.Contains("updated", notification.Message);
    }

    [Fact]
    public void SendNotification_DeleteOperation_GeneratesDeleteMessage()
    {
        var service = new NotificationService();

        service.SendNotification("Department", "5", "Engineering", EntityOperation.DELETE, "Admin");

        var notification = service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains("deleted", notification.Message);
        Assert.Contains("Engineering", notification.Message);
    }

    [Fact]
    public void SendNotification_NullUserName_DefaultsToSystem()
    {
        var service = new NotificationService();

        service.SendNotification("Student", "1", "Test", EntityOperation.CREATE, null);

        var notification = service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        var service = new NotificationService();

        // Drain any existing notifications first
        while (service.ReceiveNotification() != null) { }

        var notification = service.ReceiveNotification();

        Assert.Null(notification);
    }

    [Fact]
    public void SendAndReceive_MultiplNotifications_FIFO_Order()
    {
        var service = new NotificationService();

        // Drain existing
        while (service.ReceiveNotification() != null) { }

        service.SendNotification("Student", "1", "First", EntityOperation.CREATE);
        service.SendNotification("Course", "2", "Second", EntityOperation.UPDATE);
        service.SendNotification("Department", "3", "Third", EntityOperation.DELETE);

        var first = service.ReceiveNotification();
        var second = service.ReceiveNotification();
        var third = service.ReceiveNotification();

        Assert.Equal("Student", first!.EntityType);
        Assert.Equal("Course", second!.EntityType);
        Assert.Equal("Department", third!.EntityType);
    }

    [Fact]
    public void SendNotification_SetsCreatedAtToCurrentTime()
    {
        var service = new NotificationService();
        var before = DateTime.Now.AddSeconds(-1);

        service.SendNotification("Student", "1", "Test", EntityOperation.CREATE);

        var notification = service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.True(notification.CreatedAt >= before);
        Assert.True(notification.CreatedAt <= DateTime.Now.AddSeconds(1));
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        var service = new NotificationService();

        // Should not throw (no-op in current implementation)
        var exception = Record.Exception(() => service.MarkAsRead(999));

        Assert.Null(exception);
    }

    [Fact]
    public void Dispose_DoesNotThrow()
    {
        var service = new NotificationService();

        var exception = Record.Exception(() => service.Dispose());

        Assert.Null(exception);
    }

    [Theory]
    [InlineData(EntityOperation.CREATE, "created")]
    [InlineData(EntityOperation.UPDATE, "updated")]
    [InlineData(EntityOperation.DELETE, "deleted")]
    public void SendNotification_AllOperations_GenerateCorrectVerb(EntityOperation operation, string expectedVerb)
    {
        var service = new NotificationService();

        service.SendNotification("Entity", "1", "TestEntity", operation, "User");

        var notification = service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains(expectedVerb, notification.Message);
    }
}

