using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Data;

public class SchoolContextTests
{
    [Fact]
    public void CanAddAndRetrieveStudent()
    {
        using var context = TestDbContext.Create();
        var student = new Student
        {
            LastName = "Test",
            FirstMidName = "Student",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        context.Students.Add(student);
        context.SaveChanges();

        var retrieved = context.Students.First();
        Assert.Equal("Test", retrieved.LastName);
        Assert.Equal("Student", retrieved.FirstMidName);
        Assert.Equal(new DateTime(2023, 9, 1), retrieved.EnrollmentDate);
    }

    [Fact]
    public void CanAddAndRetrieveCourse()
    {
        using var context = TestDbContext.Create();
        var dept = new Department { DepartmentID = 1, Name = "Test", Budget = 100m, StartDate = DateTime.Now };
        context.Departments.Add(dept);
        var course = new Course { CourseID = 1001, Title = "Intro to Testing", Credits = 3, DepartmentID = 1 };

        context.Courses.Add(course);
        context.SaveChanges();

        var retrieved = context.Courses.Find(1001);
        Assert.NotNull(retrieved);
        Assert.Equal("Intro to Testing", retrieved.Title);
        Assert.Equal(3, retrieved.Credits);
    }

    [Fact]
    public void CanAddAndRetrieveDepartment()
    {
        using var context = TestDbContext.Create();
        var dept = new Department
        {
            Name = "Computer Science",
            Budget = 250000m,
            StartDate = new DateTime(2000, 9, 1)
        };

        context.Departments.Add(dept);
        context.SaveChanges();

        var retrieved = context.Departments.First();
        Assert.Equal("Computer Science", retrieved.Name);
        Assert.Equal(250000m, retrieved.Budget);
    }

    [Fact]
    public void CanAddAndRetrieveInstructor()
    {
        using var context = TestDbContext.Create();
        var instructor = new Instructor
        {
            LastName = "Doe",
            FirstMidName = "Jane",
            HireDate = new DateTime(2015, 8, 1)
        };

        context.Instructors.Add(instructor);
        context.SaveChanges();

        var retrieved = context.Instructors.First();
        Assert.Equal("Doe", retrieved.LastName);
        Assert.Equal("Jane", retrieved.FirstMidName);
    }

    [Fact]
    public void CourseAssignment_HasCompositeKey()
    {
        using var context = TestDbContext.Create();
        var instructor = new Instructor { ID = 1, LastName = "X", FirstMidName = "Y", HireDate = DateTime.Now };
        var dept = new Department { DepartmentID = 1, Name = "Dept", Budget = 0, StartDate = DateTime.Now };
        var course = new Course { CourseID = 100, Title = "C", Credits = 3, DepartmentID = 1 };
        context.Instructors.Add(instructor);
        context.Departments.Add(dept);
        context.Courses.Add(course);
        context.SaveChanges();

        var assignment = new CourseAssignment { CourseID = 100, InstructorID = 1 };
        context.CourseAssignments.Add(assignment);
        context.SaveChanges();

        var retrieved = context.CourseAssignments.Find(100, 1);
        Assert.NotNull(retrieved);
    }

    [Fact]
    public void Student_Enrollment_Relationship()
    {
        using var context = TestDbContext.Create();
        var dept = new Department { DepartmentID = 1, Name = "Dept", Budget = 0, StartDate = DateTime.Now };
        var course = new Course { CourseID = 100, Title = "Test", Credits = 3, DepartmentID = 1 };
        var student = new Student { ID = 1, LastName = "S", FirstMidName = "T", EnrollmentDate = DateTime.Now };
        context.Departments.Add(dept);
        context.Courses.Add(course);
        context.Students.Add(student);
        context.SaveChanges();

        var enrollment = new Enrollment { CourseID = 100, StudentID = 1, Grade = Grade.A };
        context.Enrollments.Add(enrollment);
        context.SaveChanges();

        var studentWithEnrollments = context.Students
            .Include(s => s.Enrollments)
            .First(s => s.ID == 1);
        Assert.Single(studentWithEnrollments.Enrollments);
        Assert.Equal(Grade.A, studentWithEnrollments.Enrollments.First().Grade);
    }

    [Fact]
    public void Instructor_OfficeAssignment_OneToOne()
    {
        using var context = TestDbContext.Create();
        var instructor = new Instructor
        {
            ID = 1,
            LastName = "Prof",
            FirstMidName = "Test",
            HireDate = DateTime.Now,
            OfficeAssignment = new OfficeAssignment { InstructorID = 1, Location = "Room 101" }
        };
        context.Instructors.Add(instructor);
        context.SaveChanges();

        var retrieved = context.Instructors
            .Include(i => i.OfficeAssignment)
            .First(i => i.ID == 1);
        Assert.NotNull(retrieved.OfficeAssignment);
        Assert.Equal("Room 101", retrieved.OfficeAssignment.Location);
    }

    [Fact]
    public void Department_InstructorAdministrator_Relationship()
    {
        using var context = TestDbContext.Create();
        var instructor = new Instructor { ID = 1, LastName = "Admin", FirstMidName = "Dept", HireDate = DateTime.Now };
        context.Instructors.Add(instructor);
        var dept = new Department { Name = "CS", Budget = 100000m, StartDate = DateTime.Now, InstructorID = 1 };
        context.Departments.Add(dept);
        context.SaveChanges();

        var retrieved = context.Departments.Include(d => d.Administrator).First();
        Assert.NotNull(retrieved.Administrator);
        Assert.Equal("Admin", retrieved.Administrator.LastName);
    }
}

