using ContosoUniversity.Models;

namespace ContosoUniversity.Tests;

public class ModelTests
{
    [Fact]
    public void Person_FullName_ReturnsLastNameCommaFirstName()
    {
        var student = new Student { LastName = "Smith", FirstMidName = "John", EnrollmentDate = DateTime.Now };

        Assert.Equal("Smith, John", student.FullName);
    }

    [Fact]
    public void Person_FullName_WithDifferentNames()
    {
        var instructor = new Instructor { LastName = "O'Brien", FirstMidName = "Mary-Jane", HireDate = DateTime.Now };

        Assert.Equal("O'Brien, Mary-Jane", instructor.FullName);
    }

    [Fact]
    public void Enrollment_Grade_CanBeNull()
    {
        var enrollment = new Enrollment { EnrollmentID = 1, CourseID = 1, StudentID = 1, Grade = null };

        Assert.Null(enrollment.Grade);
    }

    [Theory]
    [InlineData(Grade.A)]
    [InlineData(Grade.B)]
    [InlineData(Grade.C)]
    [InlineData(Grade.D)]
    [InlineData(Grade.F)]
    public void Enrollment_Grade_AllValuesValid(Grade grade)
    {
        var enrollment = new Enrollment { Grade = grade };

        Assert.Equal(grade, enrollment.Grade);
    }

    [Fact]
    public void Course_Properties_SetCorrectly()
    {
        var course = new Course
        {
            CourseID = 1050,
            Title = "Chemistry",
            Credits = 3,
            DepartmentID = 2,
            TeachingMaterialImagePath = "/uploads/chem.jpg"
        };

        Assert.Equal(1050, course.CourseID);
        Assert.Equal("Chemistry", course.Title);
        Assert.Equal(3, course.Credits);
        Assert.Equal(2, course.DepartmentID);
        Assert.Equal("/uploads/chem.jpg", course.TeachingMaterialImagePath);
    }

    [Fact]
    public void Department_Properties_SetCorrectly()
    {
        var dept = new Department
        {
            DepartmentID = 1,
            Name = "Engineering",
            Budget = 350000m,
            StartDate = new DateTime(2007, 9, 1),
