using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Moq;
using System.Net;

namespace ContosoUniversity.Tests.Controllers;

/// <summary>
/// Additional tests targeting edge cases and error branches for higher coverage.
/// </summary>
public class CoursesControllerAdditionalTests
{
    private readonly Mock<IWebHostEnvironment> _envMock = new();
    private readonly Mock<ILogger<CoursesController>> _loggerMock = new();

    public CoursesControllerAdditionalTests()
    {
        _envMock.Setup(e => e.WebRootPath).Returns((string?)null);
        _envMock.Setup(e => e.ContentRootPath).Returns("/tmp/testroot");
    }

    private SchoolContext CreateContextWithCourses()
    {
        var context = TestDbContext.Create();
        var dept = new Department { DepartmentID = 1, Name = "Engineering", Budget = 100000m, StartDate = DateTime.Now };
        context.Departments.Add(dept);
        context.Courses.Add(new Course { CourseID = 1001, Title = "Chemistry", Credits = 3, DepartmentID = 1 });
        context.SaveChanges();
        return context;
    }

    [Fact]
    public void Create_Post_ValidImageUpload_SavesFileAndRedirects()
    {
        using var context = CreateContextWithCourses();
        _envMock.Setup(e => e.WebRootPath).Returns(Path.GetTempPath());
        var controller = new CoursesController(context, _envMock.Object, _loggerMock.Object);
        var course = new Course { CourseID = 2001, Title = "New Course", Credits = 3, DepartmentID = 1 };

        var content = new byte[] { 0xFF, 0xD8, 0xFF, 0xE0 }; // JPEG header bytes
        var stream = new MemoryStream(content);
        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.FileName).Returns("photo.jpg");
        fileMock.Setup(f => f.Length).Returns(content.Length);
        fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>())).Callback<Stream>(s => stream.CopyTo(s));

        var result = controller.Create(course, fileMock.Object) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        var saved = context.Courses.Find(2001);
        Assert.NotNull(saved);
        Assert.StartsWith("/Uploads/TeachingMaterials/", saved.TeachingMaterialImagePath);
    }

    [Theory]
    [InlineData(".jpg")]
    [InlineData(".jpeg")]
    [InlineData(".png")]
    [InlineData(".gif")]
    [InlineData(".bmp")]
    public void Create_Post_AllowedExtensions_AreAccepted(string ext)
    {
        using var context = CreateContextWithCourses();
        _envMock.Setup(e => e.WebRootPath).Returns(Path.GetTempPath());
        var controller = new CoursesController(context, _envMock.Object, _loggerMock.Object);
        var course = new Course { CourseID = 3000 + ext.GetHashCode(), Title = "Course", Credits = 3, DepartmentID = 1 };

        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.FileName).Returns($"test{ext}");
        fileMock.Setup(f => f.Length).Returns(1024);
        fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));

        var result = controller.Create(course, fileMock.Object) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
    }

    [Fact]
    public void Edit_Post_ValidImageUpload_ReplacesOldImage()
    {
        using var context = CreateContextWithCourses();
        _envMock.Setup(e => e.WebRootPath).Returns(Path.GetTempPath());
        var controller = new CoursesController(context, _envMock.Object, _loggerMock.Object);

        // Detach the tracked entity
        var tracked = context.Courses.Local.FirstOrDefault(c => c.CourseID == 1001);
        if (tracked != null)
            context.Entry(tracked).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

        var course = new Course
        {
            CourseID = 1001,
            Title = "Chemistry",
            Credits = 3,
            DepartmentID = 1,
            TeachingMaterialImagePath = "/Uploads/TeachingMaterials/old.jpg"
        };

        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.FileName).Returns("new.png");
        fileMock.Setup(f => f.Length).Returns(2048);
        fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));

        var result = controller.Edit(course, fileMock.Object) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
    }

    [Fact]
    public void Edit_Post_FileTooLarge_AddsModelError()
    {
        using var context = CreateContextWithCourses();
        var controller = new CoursesController(context, _envMock.Object, _loggerMock.Object);
        var course = new Course { CourseID = 1001, Title = "Chemistry", Credits = 3, DepartmentID = 1 };

        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.FileName).Returns("big.jpg");
        fileMock.Setup(f => f.Length).Returns(6 * 1024 * 1024);

        var result = controller.Edit(course, fileMock.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.True(controller.ModelState.ContainsKey("teachingMaterialImage"));
    }

    [Fact]
    public void Edit_Post_InvalidModel_ReturnsViewWithDepartmentList()
    {
        using var context = CreateContextWithCourses();
        var controller = new CoursesController(context, _envMock.Object, _loggerMock.Object);
        controller.ModelState.AddModelError("Title", "Required");
        var course = new Course { CourseID = 1001, Title = "", Credits = 3, DepartmentID = 1 };

        var result = controller.Edit(course, null!) as ViewResult;

        Assert.NotNull(result);
        Assert.NotNull(controller.ViewBag.DepartmentID);
    }

    [Fact]
    public void Create_Post_FileUploadThrows_AddsModelError()
    {
        using var context = CreateContextWithCourses();
        // Use a path that will cause Directory.CreateDirectory to fail
        _envMock.Setup(e => e.WebRootPath).Returns("/nonexistent/path/that/is/very/deeply/nested");
        _envMock.Setup(e => e.ContentRootPath).Returns("/nonexistent/path/that/is/very/deeply/nested");
        var controller = new CoursesController(context, _envMock.Object, _loggerMock.Object);
        var course = new Course { CourseID = 5001, Title = "Course", Credits = 3, DepartmentID = 1 };

        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.FileName).Returns("photo.jpg");
        fileMock.Setup(f => f.Length).Returns(1024);
        fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>())).Throws(new IOException("Disk full"));

        var result = controller.Create(course, fileMock.Object);

        // It either redirects (if directory was created but copy fails after) or returns view with error
        // The path depends on OS permissions; the key assertion is no unhandled exception
        Assert.NotNull(result);
    }
}

