using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Routing;

namespace ContosoUniversity.Tests.Controllers;

/// <summary>
/// Additional edge case tests for StudentsController and InstructorsController.
/// </summary>
public class ControllerEdgeCaseTests
{
    [Fact]
    public void StudentsController_Create_Post_ExceptionDuringSave_AddsModelError()
    {
        // Use a context that will be disposed before the operation
        var context = TestDbContext.Create();
        var controller = new StudentsController(context);

        // Force an exception by disposing context before save
        context.Dispose();

        var student = new Student
        {
            LastName = "Test",
            FirstMidName = "User",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        var result = controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.False(controller.ModelState.IsValid);
    }

    [Fact]
    public void StudentsController_Edit_Post_ExceptionDuringSave_AddsModelError()
    {
        var context = TestDbContext.Create();
        context.Students.Add(new Student { ID = 1, LastName = "Test", FirstMidName = "U", EnrollmentDate = new DateTime(2023, 1, 1) });
        context.SaveChanges();

        var controller = new StudentsController(context);
        context.Dispose();

        var student = new Student
        {
            ID = 1,
            LastName = "Updated",
            FirstMidName = "User",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        var result = controller.Edit(student) as ViewResult;

        Assert.NotNull(result);
        Assert.False(controller.ModelState.IsValid);
    }

    [Fact]
    public void StudentsController_DeleteConfirmed_ExceptionDuringSave_RedirectsWithError()
    {
        var context = TestDbContext.Create();
        var controller = new StudentsController(context);
        context.Dispose();

        var result = controller.DeleteConfirmed(1) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
    }

    [Fact]
    public void InstructorsController_Index_WithInstructorAndCourseId_PopulatesEnrollments()
    {
        using var context = TestDbContext.Create();
        var dept = new Department { DepartmentID = 1, Name = "Dept", Budget = 0, StartDate = DateTime.Now };
        context.Departments.Add(dept);

        var course = new Course { CourseID = 100, Title = "CS101", Credits = 3, DepartmentID = 1, Enrollments = new List<Enrollment>() };
        context.Courses.Add(course);

        var student = new Student { ID = 1, LastName = "S", FirstMidName = "T", EnrollmentDate = DateTime.Now };
        context.Students.Add(student);

        var enrollment = new Enrollment { CourseID = 100, StudentID = 1, Grade = Grade.A };
        context.Enrollments.Add(enrollment);

        var instructor = new Instructor
        {
            ID = 1,
            LastName = "Prof",
            FirstMidName = "X",
            HireDate = DateTime.Now,
            CourseAssignments = new List<CourseAssignment> { new CourseAssignment { InstructorID = 1, CourseID = 100 } }
        };
        context.Instructors.Add(instructor);
        context.SaveChanges();

        var controller = new InstructorsController(context);

        var result = controller.Index(1, 100) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<ContosoUniversity.Models.SchoolViewModels.InstructorIndexData>(result.Model);
        Assert.NotNull(model.Enrollments);
        Assert.Single(model.Enrollments);
    }

    [Fact]
    public void DepartmentsController_DeleteConfirmed_RemovesDepartment()
    {
        using var context = TestDbContext.Create();
        context.Departments.Add(new Department { DepartmentID = 10, Name = "ToDelete", Budget = 0, StartDate = DateTime.Now });
        context.SaveChanges();

        var controller = new DepartmentsController(context);

        var result = controller.DeleteConfirmed(10) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Null(context.Departments.Find(10));
    }

    [Fact]
    public void HomeController_About_EmptyDatabase_ReturnsEmptyList()
    {
        using var context = TestDbContext.Create();
        var controller = new HomeController(context);

        var result = controller.About() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsAssignableFrom<List<ContosoUniversity.Models.SchoolViewModels.EnrollmentDateGroup>>(result.Model);
        Assert.Empty(model);
    }
}

