using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;

namespace ContosoUniversity.Tests.Data;

public class DbInitializerTests
{
    [Fact]
    public void Initialize_EmptyDatabase_SeedsAllData()
    {
        using var context = TestDbContext.Create();

        DbInitializer.Initialize(context);

        Assert.Equal(8, context.Students.Count());
        Assert.Equal(5, context.Instructors.Count());
        Assert.Equal(4, context.Departments.Count());
        Assert.Equal(7, context.Courses.Count());
        Assert.Equal(3, context.OfficeAssignments.Count());
        Assert.Equal(8, context.CourseAssignments.Count());
        Assert.Equal(11, context.Enrollments.Count());
    }

    [Fact]
    public void Initialize_DatabaseAlreadySeeded_DoesNotDuplicate()
    {
        using var context = TestDbContext.Create();

        DbInitializer.Initialize(context);
        DbInitializer.Initialize(context);

        // Should still have same count after second call
        Assert.Equal(8, context.Students.Count());
        Assert.Equal(5, context.Instructors.Count());
    }

    [Fact]
    public void Initialize_SeedsStudentsWithCorrectData()
    {
        using var context = TestDbContext.Create();

        DbInitializer.Initialize(context);

        var carson = context.Students.FirstOrDefault(s => s.LastName == "Alexander");
        Assert.NotNull(carson);
        Assert.Equal("Carson", carson.FirstMidName);
        Assert.Equal(DateTime.Parse("2010-09-01"), carson.EnrollmentDate);
    }

    [Fact]
    public void Initialize_SeedsInstructorsWithCorrectData()
    {
        using var context = TestDbContext.Create();

        DbInitializer.Initialize(context);

        var kim = context.Instructors.FirstOrDefault(i => i.LastName == "Abercrombie");
        Assert.NotNull(kim);
        Assert.Equal("Kim", kim.FirstMidName);
        Assert.Equal(DateTime.Parse("1995-03-11"), kim.HireDate);
    }

    [Fact]
    public void Initialize_SeedsDepartmentsWithAdministrators()
    {
        using var context = TestDbContext.Create();

        DbInitializer.Initialize(context);

        var english = context.Departments.FirstOrDefault(d => d.Name == "English");
        Assert.NotNull(english);
        Assert.Equal(350000m, english.Budget);
        Assert.NotNull(english.InstructorID);
    }

    [Fact]
    public void Initialize_SeedsCoursesInCorrectDepartments()
    {
        using var context = TestDbContext.Create();

        DbInitializer.Initialize(context);

        var chemistry = context.Courses.FirstOrDefault(c => c.Title == "Chemistry");
        Assert.NotNull(chemistry);
        Assert.Equal(1050, chemistry.CourseID);
        Assert.Equal(3, chemistry.Credits);

        var engDept = context.Departments.First(d => d.Name == "Engineering");
        Assert.Equal(engDept.DepartmentID, chemistry.DepartmentID);
    }

    [Fact]
    public void Initialize_SeedsOfficeAssignments()
    {
        using var context = TestDbContext.Create();

        DbInitializer.Initialize(context);

        var fakhouri = context.Instructors.First(i => i.LastName == "Fakhouri");
        var office = context.OfficeAssignments.FirstOrDefault(o => o.InstructorID == fakhouri.ID);
        Assert.NotNull(office);
        Assert.Equal("Smith 17", office.Location);
    }

    [Fact]
    public void Initialize_SeedsCourseAssignments()
    {
        using var context = TestDbContext.Create();

        DbInitializer.Initialize(context);

        // Abercrombie teaches Composition and Literature
        var abercrombie = context.Instructors.First(i => i.LastName == "Abercrombie");
        var assignments = context.CourseAssignments.Where(ca => ca.InstructorID == abercrombie.ID).ToList();
        Assert.Equal(2, assignments.Count);
    }

    [Fact]
    public void Initialize_SeedsEnrollmentsWithGrades()
    {
        using var context = TestDbContext.Create();

        DbInitializer.Initialize(context);

        var alexander = context.Students.First(s => s.LastName == "Alexander");
        var enrollments = context.Enrollments.Where(e => e.StudentID == alexander.ID).ToList();
        Assert.Equal(3, enrollments.Count);
        Assert.Contains(enrollments, e => e.Grade == Grade.A);
        Assert.Contains(enrollments, e => e.Grade == Grade.B);
        Assert.Contains(enrollments, e => e.Grade == Grade.C);
    }

    [Fact]
    public void Initialize_SomeEnrollmentsHaveNoGrade()
    {
        using var context = TestDbContext.Create();

        DbInitializer.Initialize(context);

        var anand = context.Students.First(s => s.LastName == "Anand");
        var enrollments = context.Enrollments.Where(e => e.StudentID == anand.ID).ToList();
        Assert.Contains(enrollments, e => e.Grade == null);
    }
}

